-- ============================================================================
-- 150_fixtures_price_hourly.sql — FIXTURE deployment (demo)
-- 30 days of hourly prices (off-peak 23h-7h at 0.1299 EUR/kWh, on-peak 0.1874, peaks x1.35),
-- site 'ALL' (market price). Identical to the front fixtures (app-features/fixtures).
-- Demo: replaces the partial bronze flow data with the complete fixture.
-- ============================================================================
DELETE FROM bronze.energy_price;
REFRESH MATERIALIZED VIEW gold.price_hourly;

-- Config price-optimizer (without shiftable_kwh, no slot is advised: cap = 0).
UPDATE app.prefs
SET prefs = jsonb_set(prefs, '{price-optimizer}',
  coalesce(prefs->'price-optimizer', '{}'::jsonb)
  || jsonb_build_object('enabled', true, 'config', jsonb_build_object('shiftable_kwh', 120, 'window', '01:00-06:00')));
